        {
          "proposicao": "A metodologia descrita combina dados ambientais em tempo real e medições de resposta de risers e do FPSO para melhorar modelos de cálculo de fadiga e apoiar decisões de mitigação de risco em projetos de extensão de vida.",
          "trechos": [
            "E01e48c8b347d281a:0:694",
            "E01e48c8b347d281a:694:1393"
          ],
          "condicoes": [
